CREATE PROCEDURE [sales].[POS_PostInvoice] @CounterId UNIQUEIDENTIFIER=NULL,@ShiftId UNIQUEIDENTIFIER=NULL,@CustomerId UNIQUEIDENTIFIER=NULL,@WarehouseId UNIQUEIDENTIFIER,@SalesPersonId UNIQUEIDENTIFIER=NULL,@ItemsJson NVARCHAR(MAX),@PaymentsJson NVARCHAR(MAX)=NULL,@BillDiscount DECIMAL(18,2)=0,@RoundOff DECIMAL(18,2)=0,@Remarks NVARCHAR(1000)=NULL,@Status NVARCHAR(20)='COMPLETED',@InterState BIT=0,@DiscountAuthorizedBy NVARCHAR(256)=NULL,@CreatedBy NVARCHAR(256)=NULL
AS
BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;IF @Status NOT IN('COMPLETED','HELD','SUSPENDED')THROW 51100,'Invalid invoice status.',1;IF ISJSON(@ItemsJson)<>1 OR NOT EXISTS(SELECT 1 FROM OPENJSON(@ItemsJson))THROW 51100,'Invoice requires items.',1;
DECLARE @InvoiceId UNIQUEIDENTIFIER=NEWID(),@SeriesId UNIQUEIDENTIFIER,@Prefix NVARCHAR(20),@Next BIGINT,@Length INT,@InvoiceNumber NVARCHAR(50),@Subtotal DECIMAL(18,2)=0,@ItemDiscount DECIMAL(18,2)=0,@Tax DECIMAL(18,2)=0,@Grand DECIMAL(18,2),@Paid DECIMAL(18,2)=0,@InventoryTransactionId UNIQUEIDENTIFIER=NEWID(),@AllowNegative BIT=(SELECT TOP(1)NegativeStockAllowed FROM inventory.InventorySettings);
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;BEGIN TRAN;
SELECT TOP(1)@SeriesId=s.InvoiceSeriesId,@Prefix=s.Prefix,@Next=s.NextNumber,@Length=s.NumberLength FROM sales.InvoiceSeries s WITH(UPDLOCK,HOLDLOCK)LEFT JOIN sales.POSCounters c ON c.InvoiceSeriesId=s.InvoiceSeriesId WHERE s.IsActive=1 AND((@CounterId IS NOT NULL AND c.CounterId=@CounterId)OR(@CounterId IS NULL AND s.IsDefault=1))ORDER BY CASE WHEN @CounterId IS NOT NULL AND c.CounterId=@CounterId THEN 0 ELSE 1 END;IF @SeriesId IS NULL BEGIN ROLLBACK;THROW 51100,'Active invoice series not configured.',1;END;SET @InvoiceNumber=CONCAT(@Prefix,'-',RIGHT(REPLICATE('0',@Length)+CONVERT(NVARCHAR(20),@Next),@Length));UPDATE sales.InvoiceSeries SET NextNumber=NextNumber+1 WHERE InvoiceSeriesId=@SeriesId;
SELECT @Subtotal=SUM(Quantity*UnitPrice),@ItemDiscount=SUM(CASE WHEN DiscountAmount>0 THEN DiscountAmount ELSE Quantity*UnitPrice*DiscountPercentage/100 END),@Tax=SUM(((Quantity*UnitPrice)-CASE WHEN DiscountAmount>0 THEN DiscountAmount ELSE Quantity*UnitPrice*DiscountPercentage/100 END)*TaxPercentage/100)FROM OPENJSON(@ItemsJson)WITH(ProductId UNIQUEIDENTIFIER,Quantity DECIMAL(18,4),UnitPrice DECIMAL(18,4),DiscountPercentage DECIMAL(5,2),DiscountAmount DECIMAL(18,2),TaxPercentage DECIMAL(5,2));SET @Grand=ROUND(@Subtotal-@ItemDiscount-@BillDiscount+@Tax+@RoundOff,2);IF @Grand<0 BEGIN ROLLBACK;THROW 51100,'Invoice total cannot be negative.',1;END;IF ISJSON(@PaymentsJson)=1 SELECT @Paid=ISNULL(SUM(Amount),0)FROM OPENJSON(@PaymentsJson)WITH(Amount DECIMAL(18,2));IF @Paid>@Grand BEGIN ROLLBACK;THROW 51100,'Payment exceeds invoice total.',1;END;
INSERT sales.SalesInvoices(InvoiceId,InvoiceNumber,InvoiceDate,CounterId,ShiftId,CustomerId,WarehouseId,SalesPersonId,Subtotal,DiscountAmount,TaxAmount,RoundOff,GrandTotal,PaidAmount,Status,Remarks,CreatedBy)VALUES(@InvoiceId,@InvoiceNumber,SYSUTCDATETIME(),@CounterId,@ShiftId,@CustomerId,@WarehouseId,@SalesPersonId,@Subtotal,@ItemDiscount+@BillDiscount,@Tax,@RoundOff,@Grand,@Paid,@Status,@Remarks,@CreatedBy);IF @Status='COMPLETED' INSERT inventory.InventoryTransactions(TransactionId,TransactionNo,TransactionType,ReferenceType,ReferenceId,WarehouseId,Remarks,CreatedBy)VALUES(@InventoryTransactionId,@InvoiceNumber+'-STK','SALE','SALES_INVOICE',@InvoiceId,@WarehouseId,@Remarks,@CreatedBy);
DECLARE item_cursor CURSOR LOCAL FAST_FORWARD FOR SELECT ProductId,Barcode,Quantity,UnitPrice,DiscountPercentage,DiscountAmount,TaxPercentage FROM OPENJSON(@ItemsJson)WITH(ProductId UNIQUEIDENTIFIER,Barcode NVARCHAR(100),Quantity DECIMAL(18,4),UnitPrice DECIMAL(18,4),DiscountPercentage DECIMAL(5,2),DiscountAmount DECIMAL(18,2),TaxPercentage DECIMAL(5,2));DECLARE @ProductId UNIQUEIDENTIFIER,@Barcode NVARCHAR(100),@Quantity DECIMAL(18,4),@UnitPrice DECIMAL(18,4),@DiscountPercentage DECIMAL(5,2),@DiscountAmount DECIMAL(18,2),@TaxPercentage DECIMAL(5,2),@Taxable DECIMAL(18,2),@TaxAmount DECIMAL(18,2),@LineTotal DECIMAL(18,2),@ItemId UNIQUEIDENTIFIER,@BalanceId UNIQUEIDENTIFIER,@Available DECIMAL(18,4),@AverageCost DECIMAL(18,4);
OPEN item_cursor;FETCH NEXT FROM item_cursor INTO @ProductId,@Barcode,@Quantity,@UnitPrice,@DiscountPercentage,@DiscountAmount,@TaxPercentage;WHILE @@FETCH_STATUS=0 BEGIN IF @Quantity<=0 OR @UnitPrice<0 BEGIN CLOSE item_cursor;DEALLOCATE item_cursor;ROLLBACK;THROW 51100,'Invalid invoice item quantity or price.',1;END;SET @DiscountAmount=CASE WHEN ISNULL(@DiscountAmount,0)>0 THEN @DiscountAmount ELSE @Quantity*@UnitPrice*ISNULL(@DiscountPercentage,0)/100 END;SET @Taxable=@Quantity*@UnitPrice-@DiscountAmount;SET @TaxAmount=@Taxable*ISNULL(@TaxPercentage,0)/100;SET @LineTotal=ROUND(@Taxable+@TaxAmount,2);SET @ItemId=NEWID();INSERT sales.SalesInvoiceItems(InvoiceItemId,InvoiceId,ProductId,Barcode,Quantity,UnitPrice,DiscountPercentage,DiscountAmount,TaxPercentage,TaxAmount,LineTotal)VALUES(@ItemId,@InvoiceId,@ProductId,@Barcode,@Quantity,@UnitPrice,ISNULL(@DiscountPercentage,0),@DiscountAmount,ISNULL(@TaxPercentage,0),@TaxAmount,@LineTotal);IF @DiscountAmount>0 INSERT sales.SalesDiscounts(InvoiceId,InvoiceItemId,DiscountType,DiscountMode,DiscountValue,DiscountAmount,AuthorizedBy)VALUES(@InvoiceId,@ItemId,'ITEM',CASE WHEN ISNULL(@DiscountPercentage,0)>0 THEN'PERCENTAGE'ELSE'FLAT'END,CASE WHEN ISNULL(@DiscountPercentage,0)>0 THEN @DiscountPercentage ELSE @DiscountAmount END,@DiscountAmount,@DiscountAuthorizedBy);IF @TaxAmount>0 BEGIN IF @InterState=1 INSERT sales.SalesTaxes(InvoiceId,InvoiceItemId,TaxType,TaxPercentage,TaxableAmount,TaxAmount)VALUES(@InvoiceId,@ItemId,'IGST',@TaxPercentage,@Taxable,@TaxAmount);ELSE INSERT sales.SalesTaxes(InvoiceId,InvoiceItemId,TaxType,TaxPercentage,TaxableAmount,TaxAmount)VALUES(@InvoiceId,@ItemId,'CGST',@TaxPercentage/2,@Taxable,@TaxAmount/2),(@InvoiceId,@ItemId,'SGST',@TaxPercentage/2,@Taxable,@TaxAmount/2);END;
IF @Status='COMPLETED' BEGIN SELECT @BalanceId=InventoryBalanceId,@Available=QuantityAvailable,@AverageCost=AverageCost FROM inventory.InventoryBalances WITH(UPDLOCK,HOLDLOCK)WHERE ProductId=@ProductId AND WarehouseId=@WarehouseId AND ZoneId IS NULL AND BinId IS NULL AND BatchNo IS NULL AND SerialNo IS NULL;IF @BalanceId IS NULL OR(ISNULL(@AllowNegative,0)=0 AND @Available<@Quantity)BEGIN CLOSE item_cursor;DEALLOCATE item_cursor;ROLLBACK;THROW 51101,'Insufficient stock for invoice.',1;END;UPDATE inventory.InventoryBalances SET QuantityOnHand=QuantityOnHand-@Quantity,LastUpdated=SYSUTCDATETIME(),ModifiedOn=SYSUTCDATETIME(),ModifiedBy=@CreatedBy WHERE InventoryBalanceId=@BalanceId;INSERT inventory.InventoryTransactionDetails(TransactionId,ProductId,Quantity,UnitCost)VALUES(@InventoryTransactionId,@ProductId,@Quantity,ISNULL(@AverageCost,0));END;FETCH NEXT FROM item_cursor INTO @ProductId,@Barcode,@Quantity,@UnitPrice,@DiscountPercentage,@DiscountAmount,@TaxPercentage;END;CLOSE item_cursor;DEALLOCATE item_cursor;
IF @BillDiscount>0 INSERT sales.SalesDiscounts(InvoiceId,DiscountType,DiscountMode,DiscountValue,DiscountAmount,AuthorizedBy)VALUES(@InvoiceId,'BILL','FLAT',@BillDiscount,@BillDiscount,@DiscountAuthorizedBy);IF ISJSON(@PaymentsJson)=1 INSERT sales.SalesPayments(InvoiceId,PaymentMethodId,Amount,ReferenceNumber,CreatedBy)SELECT @InvoiceId,m.PaymentMethodId,j.Amount,j.ReferenceNumber,@CreatedBy FROM OPENJSON(@PaymentsJson)WITH(MethodCode NVARCHAR(30),Amount DECIMAL(18,2),ReferenceNumber NVARCHAR(100))j INNER JOIN sales.PaymentMethods m ON m.MethodCode=j.MethodCode AND m.IsActive=1;
IF @ShiftId IS NOT NULL AND EXISTS(SELECT 1 FROM OPENJSON(@PaymentsJson)j INNER JOIN sales.PaymentMethods m ON m.MethodCode=JSON_VALUE(j.value,'$.MethodCode')WHERE m.MethodCode='CASH')INSERT sales.CashDrawer(ShiftId,EntryType,Amount,ReferenceType,ReferenceId,CreatedBy)SELECT @ShiftId,'SALE',SUM(CONVERT(DECIMAL(18,2),JSON_VALUE(j.value,'$.Amount'))),'SALES_INVOICE',@InvoiceId,@CreatedBy FROM OPENJSON(@PaymentsJson)j WHERE JSON_VALUE(j.value,'$.MethodCode')='CASH';COMMIT;SELECT @InvoiceId InvoiceId,@InvoiceNumber InvoiceNumber,@Grand GrandTotal,@Paid PaidAmount,@Status Status;END;
